import itertools,time
n=13;N=1<<n;F=N-1

def span(vs):
 s={0}
 for v in vs:s|={x^v for x in s}
 return s

def rankbasis(rows):
 P={}
 for v in rows:
  while v:
   p=v.bit_length()-1
   if p in P:v^=P[p]
   else:P[p]=v;break
 return P

def footprint(Union):
 mons=sorted(range(N),key=lambda x:(x.bit_count(),x));ix={x:i for i,x in enumerate(mons)}
 rows=[]
 for x in Union:
  a=F^x;free=F^a;t=free;v=0
  while True:
   v^=1<<ix[a|t]
   if not t:break
   t=(t-1)&free
  rows.append(v)
